<?php $this->assign('title', h($site->name) . ' | Sitios'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><a class="small" href="/admin/sites">← Sitios</a><h1 class="h2 mb-1"><?= h($site->name) ?></h1><p class="text-muted mb-0"><?= h($site->subdomain) ?> · <?= h($site->user->email ?? '') ?></p></div><div class="d-flex gap-2"><a class="btn btn-outline-primary" target="_blank" rel="noopener" href="<?= h($publicUrl) ?>">Abrir sitio</a><span class="badge text-bg-<?= $site->status === 'published' ? 'success' : ($site->status === 'paused' ? 'warning' : 'secondary') ?> align-self-center"><?= h($site->status) ?></span></div></div>
<div class="row g-4"><div class="col-lg-8"><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Configuración</h2><dl class="row mb-0"><dt class="col-sm-4">Plantilla</dt><dd class="col-sm-8"><?= h($site->template->name ?? '') ?></dd><dt class="col-sm-4">Tema</dt><dd class="col-sm-8"><?= h($site->theme->name ?? '') ?></dd><dt class="col-sm-4">Suscripción</dt><dd class="col-sm-8"><?= h($subscription->plan_slug ?? 'Sin suscripción') ?> · <?= h($subscription->status ?? '') ?></dd><dt class="col-sm-4">Pausa</dt><dd class="col-sm-8"><?= h($site->paused_reason ?: '—') ?></dd><dt class="col-sm-4">SEO</dt><dd class="col-sm-8"><?= h($site->seo_title ?: '—') ?></dd><dt class="col-sm-4">Contenido</dt><dd class="col-sm-8"><?= count($site->catalog_categories ?? []) ?> categorías · <?= count($site->catalog_products ?? []) ?> productos/servicios</dd></dl></div></section>
<section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Dominios asociados</h2><?php foreach ($site->domains as $domain): ?><div class="border-bottom py-2 d-flex justify-content-between"><span><?= h($domain->domain) ?></span><small><?= h($domain->type) ?> · <?= $domain->verified ? 'verificado' : 'sin verificar' ?></small></div><?php endforeach; ?></div></section>
<section class="card admin-card"><div class="card-body"><h2 class="h5">Auditoría del sitio</h2><?php foreach ($audits as $audit): ?><div class="border-bottom py-2"><strong class="small"><?= h($audit->action) ?></strong><small class="d-block text-muted"><?= h($audit->created) ?></small></div><?php endforeach; ?></div></section></div>
<aside class="col-lg-4"><section class="card admin-card"><div class="card-body"><h2 class="h5">Acciones administrativas</h2><?php if ($site->status !== 'paused'): ?><?= $this->Form->create(null, ['url' => '/admin/sites/' . $site->id . '/pause', 'class' => 'mb-2', 'data-admin-confirm' => '¿Pausar este sitio? El contenido no se eliminará.']) ?><textarea class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo de la pausa"></textarea><button class="btn btn-warning w-100">Pausar sitio</button><?= $this->Form->end() ?><?php endif; ?><?php if ($site->status === 'paused' && $site->paused_reason === 'manual_admin'): ?><?= $this->Form->create(null, ['url' => '/admin/sites/' . $site->id . '/reactivate', 'class' => 'mb-2', 'data-admin-confirm' => '¿Reactivar este sitio?']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo de la reactivación"><button class="btn btn-success w-100">Reactivar sitio</button><?= $this->Form->end() ?><?php endif; ?><?php if ($site->status !== 'draft'): ?><?= $this->Form->create(null, ['url' => '/admin/sites/' . $site->id . '/unpublish', 'data-admin-confirm' => '¿Despublicar este sitio? El contenido seguirá disponible en el panel.']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo para despublicar"><button class="btn btn-outline-danger w-100">Despublicar</button><?= $this->Form->end() ?><?php endif; ?></div></section></aside></div>
